using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.SGR.RecuperacionPassword;using GraphApi.Services.SGR.RecuperacionPassword;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.SGR.RecuperacionPassword{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de RecuperacionPasswords: creación, actualización y eliminación.")]    public class RecuperacionPasswordMutation    {        [Authorize]        [GraphQLName("createRecuperacionPassword")]        [GraphQLDescription("Crea un nuevo RecuperacionPassword usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadRecuperacionPassword> CreateRecuperacionPasswordAsync(            [GraphQLDescription("Datos necesarios para crear el RecuperacionPassword.")]            clCreateRecuperacionPassword objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de RecuperacionPassword.")]            IRecuperacionPasswordService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateRecuperacionPassword(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateRecuperacionPassword")]        [GraphQLDescription("Actualiza los campos especificados de un RecuperacionPassword existente.")]        public async Task<clReadRecuperacionPassword?> UpdateRecuperacionPasswordAsync(            [GraphQLDescription("Datos del RecuperacionPassword a actualizar.")]            clUpdateRecuperacionPassword objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de RecuperacionPassword.")]            IRecuperacionPasswordService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateRecuperacionPassword(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteRecuperacionPassword")]        [GraphQLDescription("Elimina un RecuperacionPassword por su ID.")]        public async Task<bool> delRecuperacionPasswordAsync(            [GraphQLDescription("ID del RecuperacionPassword a eliminar.")]            int nRecuperacionPasswordID,            [Service]            [GraphQLDescription("Servicio para operaciones de RecuperacionPassword.")]            IRecuperacionPasswordService objService        )        {            return await objService.DeleteRecuperacionPassword(nRecuperacionPasswordID);        }    }}